package main

import "fmt"

func main() {
	var s []int // nil slice: ptr=nil, len=0, cap=0
	fmt.Printf("start: len=%d cap=%d nil=%t\n", len(s), cap(s), s == nil)

	for i := 1; i <= 5; i++ {
		s = append(s, i) // ALWAYS reassign: append may return a new header
		fmt.Printf("after append %d: len=%d cap=%d\n", i, len(s), cap(s))
	}
}

package main

import "fmt"

func main() {
	s := []int{10, 20, 30, 40, 50}
	sub := s[1:3] // view of s[1], s[2]; shares the backing array
	fmt.Printf("s=%v sub=%v len(sub)=%d cap(sub)=%d\n", s, sub, len(sub), cap(sub))

	sub[0] = 99 // writes through to the SAME memory as s[1]
	fmt.Printf("after sub[0]=99 -> s=%v sub=%v\n", s, sub)
}

package main

import "fmt"

func main() {
	original := []int{1, 2, 3, 4, 5}

	// DANGER: sub has spare capacity from original's backing array.
	sub := original[0:2] // len=2, cap=5
	sub = append(sub, 99) // writes into original[2]! overwrites 3
	fmt.Printf("danger: original=%v sub=%v\n", original, sub)

	// FIX: three-index slice caps capacity so append must reallocate.
	original2 := []int{1, 2, 3, 4, 5}
	safe := original2[0:2:2] // len=2, cap=2 (max-low = 2-0)
	safe = append(safe, 99)  // cap exhausted -> new backing array, original2 untouched
	fmt.Printf("safe:   original2=%v safe=%v\n", original2, safe)
}

package main

import "fmt"

func main() {
	// Preallocate: len=0, cap=4 -> appends 1..4 with zero reallocations.
	buf := make([]int, 0, 4)
	fmt.Printf("buf: len=%d cap=%d\n", len(buf), cap(buf))
	for i := 1; i <= 4; i++ {
		buf = append(buf, i)
	}
	fmt.Printf("filled: %v len=%d cap=%d\n", buf, len(buf), cap(buf))

	// copy into an independent slice; returns number of elements copied.
	dst := make([]int, 2) // len=2, cap=2 -> only 2 elements fit
	n := copy(dst, buf)   // copies min(len(dst), len(buf)) = 2
	dst[0] = -1           // does NOT affect buf (separate backing array)
	fmt.Printf("copied n=%d dst=%v buf=%v\n", n, dst, buf)
}
